<section class="page"><h1>Himoyalangan fayllar</h1><p class="muted">Fayl qo‘shish va almashtirish uchun o‘z e’loningizning batafsil sahifasiga o‘ting.</p><form class="app-form file-search" method="get"><input name="route" value="files" type="hidden"><label>Fayl nomi yoki tavsifidan qidirish<input name="q" maxlength="120" value="<?=e($_GET['q']??'')?>"></label><button class="primary">Qidirish</button></form><div class="stack"><?php foreach($items as $x):?><article class="panel attachment"><div><h2><a href="<?=url('file-download',['id'=>$x['id']])?>"><?=e($x['original_name'])?></a></h2><p><?=e($x['description'])?></p><p class="muted"><?=e($x['mime'])?> · <?=round($x['size']/1024)?> KB · <?=e($x['title'])?></p></div><a class="secondary" href="<?=url('listing',['id'=>$x['listing_id']])?>">E’longa o‘tish</a></article><?php endforeach?><?php if(!$items):?><div class="empty">Fayl topilmadi.</div><?php endif?></div></section>
